using Microsoft.EntityFrameworkCore;
using SupportAgent.Api.Authorization;
using SupportAgent.Api.Security;
using SupportAgent.Core.ExternalData;
using SupportAgent.Infrastructure.Data;
using SupportAgent.Infrastructure.ExternalData;
namespace SupportAgent.Api.Endpoints;

public record CreateExternalSourceRequest(string Name,string SecretKey,string? Description,bool Enabled);
public record SaveExternalMappingRequest(string Schema,string Table,string ObjectType,string BusinessEntityName,string DisplayName,string Description,string Concepts,bool Enabled,IReadOnlyList<SaveExternalFieldRequest> Fields,string? DefaultRecencyField=null);
public record SaveExternalFieldRequest(string ExternalColumnName,string BusinessFieldName,string DisplayName,string Description,string DataType,string Concepts,bool IsQueryable,bool IsSensitive);
public record SaveExternalRelationshipRequest(string Name,string? Description,string? Concepts,string RelationshipType,string? DiscoveredForeignKeyName,string FromEntity,string FromField,string ToEntity,string ToField,bool Enabled);
public record SaveExternalScopeRequest(string Name,string Description,bool Enabled,IReadOnlyList<Guid> EntityIds);
public record SetExternalScopeEnabledRequest(bool Enabled);
public record SetExternalSourceEnabledRequest(bool Enabled);

public static class ExternalDataSourceEndpoints
{
 public static IEndpointRouteBuilder MapExternalDataSourceEndpoints(this IEndpointRouteBuilder app)
 {
  var query=app.MapGroup("/api/data-sources").RequireAuthorization(AuthorizationPolicies.AiAccess);
  query.MapGet("/",async(SupportAgentDbContext db,CancellationToken ct)=>await db.ExternalDataSources.AsNoTracking().Where(x=>x.IsEnabled).Select(x=>new ExternalDataSourceSummary(x.Id,x.Name,x.Provider.ToString(),x.IsEnabled,x.Entities.Count(e=>e.IsEnabled&&e.IsValid))).ToListAsync(ct));
  query.MapGet("/{id:guid}/scopes",async(Guid id,SupportAgentDbContext db,CancellationToken ct)=>await db.ExternalDataScopes.AsNoTracking().Where(x=>x.ExternalDataSourceId==id&&x.IsEnabled).Select(x=>new ExternalScopeSummary(x.Id,x.Name,x.Description,x.IsEnabled,x.Entities.Count,x.Entities.Select(e=>e.Entity.BusinessEntityName).ToList())).ToListAsync(ct));
  var admin=app.MapGroup("/api/admin/data-sources").RequireAuthorization(AuthorizationPolicies.AdminOnly);
  admin.MapGet("/",async(SupportAgentDbContext db,CancellationToken ct)=>await db.ExternalDataSources.AsNoTracking().Select(x=>new ExternalDataSourceSummary(x.Id,x.Name,x.Provider.ToString(),x.IsEnabled,x.Entities.Count(e=>e.IsEnabled&&e.IsValid))).ToListAsync(ct));
  admin.MapPost("/",Create).AddEndpointFilter<AntiforgeryEndpointFilter>();
  admin.MapPost("/{id:guid}/test",Test).AddEndpointFilter<AntiforgeryEndpointFilter>();
  admin.MapPost("/{id:guid}/discover",Discover).AddEndpointFilter<AntiforgeryEndpointFilter>();
  admin.MapPost("/{id:guid}/enabled",SetEnabled).AddEndpointFilter<AntiforgeryEndpointFilter>();
  admin.MapGet("/{id:guid}/mappings",async(Guid id,SupportAgentDbContext db,CancellationToken ct)=>Results.Ok(await db.ExternalEntityMappings.AsNoTracking().Where(x=>x.ExternalDataSourceId==id).Select(x=>new{x.Id,x.ExternalSchemaName,x.ExternalTableName,x.BusinessEntityName,x.DisplayName,x.Description,x.Concepts,x.DefaultRecencyField,x.IsEnabled,x.IsValid,x.ValidationMessage,Fields=x.Fields.Select(f=>new{f.ExternalColumnName,f.BusinessFieldName,f.DisplayName,f.Description,f.Concepts,f.IsQueryable,f.IsSensitive})}).ToListAsync(ct)));
  admin.MapPost("/{id:guid}/mappings",SaveMapping).AddEndpointFilter<AntiforgeryEndpointFilter>();
  admin.MapGet("/{id:guid}/relationships",async(Guid id,SupportAgentDbContext db,CancellationToken ct)=>Results.Ok(await db.ExternalRelationshipMappings.AsNoTracking().Where(x=>x.ExternalDataSourceId==id).ToListAsync(ct)));
  admin.MapPost("/{id:guid}/relationships",SaveRelationship).AddEndpointFilter<AntiforgeryEndpointFilter>();
  admin.MapGet("/{id:guid}/scopes",async(Guid id,SupportAgentDbContext db,CancellationToken ct)=>Results.Ok(await db.ExternalDataScopes.AsNoTracking().Where(x=>x.ExternalDataSourceId==id).Select(x=>new{x.Id,x.Name,x.Description,x.IsEnabled,EntityIds=x.Entities.Select(e=>e.ExternalEntityMappingId).ToList(),EntityNames=x.Entities.Select(e=>e.Entity.DisplayName!=""?e.Entity.DisplayName:e.Entity.BusinessEntityName).ToList()}).ToListAsync(ct)));
  admin.MapPost("/{id:guid}/scopes",SaveScope).AddEndpointFilter<AntiforgeryEndpointFilter>();
  admin.MapPost("/{id:guid}/scopes/{scopeId:guid}/enabled",SetScopeEnabled).AddEndpointFilter<AntiforgeryEndpointFilter>();
  return app;
 }
 static async Task<IResult> Create(CreateExternalSourceRequest r,SupportAgentDbContext db,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.SecretKey))return Results.BadRequest(new{error="Name and secret key are required."});var name=r.Name.Trim();var key=r.SecretKey.Trim();if(name.Length>200)return Results.BadRequest(new{error="Data source name cannot exceed 200 characters."});if(key.Length>200||key.Any(c=>!char.IsLetterOrDigit(c)&&c!='_'))return Results.BadRequest(new{error="Secret key must be a configuration reference of at most 200 letters, numbers, or underscores, not a connection string."});if((r.Description?.Length??0)>1000)return Results.BadRequest(new{error="Description cannot exceed 1000 characters."});var x=new ExternalDataSource{Id=Guid.NewGuid(),Name=name,SecretKey=key,Description=r.Description,Provider=ExternalDataSourceProvider.SqlServer,IsEnabled=r.Enabled,CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow};db.Add(x);await db.SaveChangesAsync(ct);return Results.Created($"/api/admin/data-sources/{x.Id}",new{x.Id,x.Name,Provider=x.Provider.ToString(),x.IsEnabled,x.Description});}
 static async Task<IResult> Test(Guid id,SupportAgentDbContext db,IExternalDataSourceSecretProvider secrets,IEnumerable<IExternalDataSourceConnector> connectors,CancellationToken ct){var s=await db.ExternalDataSources.SingleOrDefaultAsync(x=>x.Id==id,ct);if(s is null)return Results.NotFound();try{return Results.Ok(await connectors.Single(x=>x.Provider==s.Provider).TestAsync(secrets.GetConnectionString(s.SecretKey),ct));}catch(ExternalDataException e){return Results.BadRequest(new{success=false,error=e.Message,code=e.Code});}}
 static async Task<IResult> Discover(Guid id,SupportAgentDbContext db,IExternalSchemaDiscoveryService discovery,CancellationToken ct){try{var objects=await discovery.DiscoverAsync(id,ct);var mapped=await db.ExternalEntityMappings.Include(x=>x.Fields).Where(x=>x.ExternalDataSourceId==id).ToListAsync(ct);foreach(var m in mapped){var physical=objects.SingleOrDefault(x=>x.Schema==m.ExternalSchemaName&&x.Name==m.ExternalTableName);var missing=physical is null?m.ExternalTableName:m.Fields.FirstOrDefault(f=>physical.Columns.All(c=>c.Name!=f.ExternalColumnName))?.ExternalColumnName;m.IsValid=missing is null;m.ValidationMessage=missing is null?null:$"Mapped object or column '{missing}' is missing and requires administrator review.";}await db.SaveChangesAsync(ct);return Results.Ok(objects.Select(o=>new{o.Schema,o.Name,o.ObjectType,o.Columns,o.Relationships,Approved=mapped.Any(m=>m.ExternalSchemaName==o.Schema&&m.ExternalTableName==o.Name&&m.IsEnabled),MappingValid=mapped.FirstOrDefault(m=>m.ExternalSchemaName==o.Schema&&m.ExternalTableName==o.Name)?.IsValid}));}catch(ExternalDataException e){return Results.BadRequest(new{error=e.Message,code=e.Code});}}
 static async Task<IResult> SetEnabled(Guid id,SetExternalSourceEnabledRequest r,SupportAgentDbContext db,CancellationToken ct){var source=await db.ExternalDataSources.SingleOrDefaultAsync(x=>x.Id==id,ct);if(source is null)return Results.NotFound();source.IsEnabled=r.Enabled;source.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);return Results.Ok(new{source.Id,source.IsEnabled});}
 static async Task<IResult> SaveMapping(Guid id,SaveExternalMappingRequest r,SupportAgentDbContext db,IExternalSchemaDiscoveryService discovery,CancellationToken ct)
 {
  if(!await db.ExternalDataSources.AnyAsync(x=>x.Id==id,ct))return Results.NotFound();
  var obj=(await discovery.DiscoverAsync(id,ct)).SingleOrDefault(x=>x.Schema==r.Schema&&x.Name==r.Table);
  if(obj is null)return Results.BadRequest(new{error="The mapped table or view was not found during trusted discovery."});
  if(string.IsNullOrWhiteSpace(r.BusinessEntityName)||r.Fields.Any(f=>obj.Columns.All(c=>c.Name!=f.ExternalColumnName)))return Results.BadRequest(new{error="Logical entity and fields must come from trusted discovery."});
  if(await db.ExternalEntityMappings.AnyAsync(x=>x.ExternalDataSourceId==id&&x.BusinessEntityName==r.BusinessEntityName&&x.ExternalTableName!=r.Table,ct))return Results.BadRequest(new{error="Logical entity names must be unique within a data source."});
  await using var transaction=db.Database.IsRelational()?await db.Database.BeginTransactionAsync(ct):null;
  var entity=await db.ExternalEntityMappings.SingleOrDefaultAsync(x=>x.ExternalDataSourceId==id&&x.ExternalSchemaName==r.Schema&&x.ExternalTableName==r.Table,ct);
  if(entity is null){entity=new(){Id=Guid.NewGuid(),ExternalDataSourceId=id,ExternalSchemaName=r.Schema,ExternalTableName=r.Table};db.Add(entity);}
  var recency=r.Fields.SingleOrDefault(f=>f.BusinessFieldName==r.DefaultRecencyField);if(recency is not null&&(!recency.IsQueryable||recency.IsSensitive||obj.Columns.Single(c=>c.Name==recency.ExternalColumnName).SqlType is not ("date" or "datetime" or "datetime2" or "smalldatetime")))return Results.BadRequest(new{error="The default recency field must be an approved date/time field."});entity.ObjectType=obj.ObjectType;entity.BusinessEntityName=r.BusinessEntityName.Trim();entity.DisplayName=string.IsNullOrWhiteSpace(r.DisplayName)?r.BusinessEntityName:r.DisplayName.Trim();entity.Description=r.Description;entity.Concepts=r.Concepts;entity.DefaultRecencyField=recency?.BusinessFieldName;entity.IsEnabled=r.Enabled;entity.IsValid=true;entity.ValidationMessage=null;
  try
  {
   await db.SaveChangesAsync(ct);
   if(db.Database.IsRelational())await db.ExternalFieldMappings.Where(x=>x.ExternalEntityMappingId==entity.Id).ExecuteDeleteAsync(ct);else db.ExternalFieldMappings.RemoveRange(await db.ExternalFieldMappings.Where(x=>x.ExternalEntityMappingId==entity.Id).ToListAsync(ct));
   var fields=r.Fields.Select(f=>{var c=obj.Columns.Single(x=>x.Name==f.ExternalColumnName);var sensitive=f.IsSensitive||Sensitive(c.Name);return new ExternalFieldMapping{Id=Guid.NewGuid(),ExternalEntityMappingId=entity.Id,ExternalColumnName=c.Name,BusinessFieldName=string.IsNullOrWhiteSpace(f.BusinessFieldName)?c.Name:f.BusinessFieldName.Trim(),DisplayName=string.IsNullOrWhiteSpace(f.DisplayName)?c.Name:f.DisplayName.Trim(),Description=f.Description,DataType=LogicalType(c.SqlType),Concepts=f.Concepts,IsQueryable=c.Supported&&f.IsQueryable&&!sensitive,IsSensitive=sensitive};}).ToList();
   db.ExternalFieldMappings.AddRange(fields);await db.SaveChangesAsync(ct);if(transaction is not null)await transaction.CommitAsync(ct);
   return Results.Ok(new{entity.Id,entity.BusinessEntityName,entity.IsEnabled,entity.IsValid});
  }
  catch(DbUpdateConcurrencyException){if(transaction is not null)await transaction.RollbackAsync(ct);return Results.Conflict(new{error="The mapping changed while it was being saved. Refresh the schema and try again."});}
 }
 static async Task<IResult> SaveRelationship(Guid id,SaveExternalRelationshipRequest r,SupportAgentDbContext db,CancellationToken ct){if(!await db.ExternalDataSources.AnyAsync(x=>x.Id==id,ct))return Results.NotFound();if(string.IsNullOrWhiteSpace(r.Name)||r.Name.Contains('.')||r.Name.Length>128)return Results.BadRequest(new{error="Relationship name must be a simple logical name."});if(r.RelationshipType is not ("ManyToOne" or "OneToMany" or "OneToOne"))return Results.BadRequest(new{error="Unsupported relationship type."});var entities=await db.ExternalEntityMappings.Where(x=>x.ExternalDataSourceId==id&&x.IsEnabled&&x.IsValid).Include(x=>x.Fields).ToListAsync(ct);var from=entities.SingleOrDefault(x=>x.BusinessEntityName==r.FromEntity);var to=entities.SingleOrDefault(x=>x.BusinessEntityName==r.ToEntity);if(from?.Fields.All(x=>!x.IsQueryable||x.BusinessFieldName!=r.FromField)!=false||to?.Fields.All(x=>!x.IsQueryable||x.BusinessFieldName!=r.ToField)!=false)return Results.BadRequest(new{error="Relationship fields must come from approved queryable mappings."});if(await db.ExternalRelationshipMappings.AnyAsync(x=>x.ExternalDataSourceId==id&&x.FromEntity==r.FromEntity&&x.Name==r.Name,ct))return Results.BadRequest(new{error="Relationship names must be unique for the source entity."});var rel=new ExternalRelationshipMapping{Id=Guid.NewGuid(),ExternalDataSourceId=id,Name=r.Name.Trim(),Description=r.Description?.Trim()??"",Concepts=r.Concepts?.Trim()??"",RelationshipType=r.RelationshipType,DiscoveredForeignKeyName=r.DiscoveredForeignKeyName,FromEntity=r.FromEntity,FromField=r.FromField,ToEntity=r.ToEntity,ToField=r.ToField,IsEnabled=r.Enabled};db.Add(rel);await db.SaveChangesAsync(ct);return Results.Ok(new{rel.Id,rel.Name});}
 static async Task<IResult> SaveScope(Guid id,SaveExternalScopeRequest r,SupportAgentDbContext db,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Name))return Results.BadRequest(new{error="Scope name is required."});if(r.EntityIds is null||r.EntityIds.Count==0)return Results.BadRequest(new{error="Select at least one approved entity."});var name=r.Name.Trim();if(await db.ExternalDataScopes.AnyAsync(x=>x.ExternalDataSourceId==id&&x.Name==name,ct))return Results.Conflict(new{error="A scope with this name already exists."});var approved=await db.ExternalEntityMappings.Where(x=>x.ExternalDataSourceId==id&&x.IsEnabled&&x.IsValid&&r.EntityIds.Contains(x.Id)).Select(x=>x.Id).ToListAsync(ct);if(approved.Count!=r.EntityIds.Distinct().Count())return Results.BadRequest(new{error="Scopes may contain only approved valid entities from this data source."});var scope=new ExternalDataScope{Id=Guid.NewGuid(),ExternalDataSourceId=id,Name=name,Description=r.Description?.Trim()??"",IsEnabled=r.Enabled,Entities=approved.Select(x=>new ExternalDataScopeEntity{ExternalEntityMappingId=x}).ToList()};db.Add(scope);await db.SaveChangesAsync(ct);return Results.Ok(new{scope.Id,scope.Name,scope.Description,scope.IsEnabled,EntityIds=approved});}
 static async Task<IResult> SetScopeEnabled(Guid id,Guid scopeId,SetExternalScopeEnabledRequest r,SupportAgentDbContext db,CancellationToken ct){var scope=await db.ExternalDataScopes.SingleOrDefaultAsync(x=>x.Id==scopeId&&x.ExternalDataSourceId==id,ct);if(scope is null)return Results.NotFound();scope.IsEnabled=r.Enabled;await db.SaveChangesAsync(ct);return Results.Ok(new{scope.Id,scope.IsEnabled});}
 static bool Sensitive(string name)=>new[]{"password","password_hash","secret","token","api_key","ssn","credit_card","bank_account"}.Any(x=>name.Contains(x,StringComparison.OrdinalIgnoreCase));
 static string LogicalType(string sql)=>sql.ToLowerInvariant() switch{"bit"=>"Boolean","date"=>"Date","datetime" or "datetime2" or "smalldatetime"=>"DateTime","decimal" or "numeric" or "money" or "smallmoney"=>"Decimal","int" or "bigint" or "smallint" or "tinyint"=>"Integer","uniqueidentifier"=>"Guid",_=>"String"};
}
